import{_ as o,a0 as i,w as s,s as p,I as l,x as t,a1 as n,A as r,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"开发者的福音：你需要知道的事 | LCTT x X-CMD","titleTemplate":false,"description":"开发者的福音：你需要知道的事 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开发者的福音：你需要知道的事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开发者的福音：你需要知道的事 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20190222 Developer happiness- What you need to know","title":"开发者的福音：你需要知道的事","tag":"202008","desc":""},"relativePath":"202008/20190222 Developer happiness- What you need to know.md","filePath":"[post].md"}'),u={name:"202008/20190222 Developer happiness- What you need to know.md"};function m(f,e,h,T,x,b){const a=i("Link");return s(),p("div",null,[e[18]||(e[18]=l("h1",{id:"开发者的福音-你需要知道的事",tabindex:"-1"},[t("开发者的福音：你需要知道的事 "),l("a",{class:"header-anchor",href:"#开发者的福音-你需要知道的事","aria-label":"Permalink to “开发者的福音：你需要知道的事”"},"​")],-1)),e[19]||(e[19]=l("blockquote",null,[l("p",null,"开发者需要快速编程的工具和自由，而不会因为合规性和安全性所困扰。")],-1)),e[20]||(e[20]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202008/07/214051ki2zitovo8zzynco.jpg",alt:""})],-1)),e[21]||(e[21]=l("p",null,"一个人需要合适的工具来完成工作。比如说没有比修车修到一半，却发现你没有完成工作的专业工具更沮丧的事情了。同样的道理也适用在开发者身上：你需要工具来发挥你的才能，而不会因为合规性和安全性的需求打断你的工作流程，这样你才可以更快速地编码。",-1)),l("p",null,[e[1]||(e[1]=t("根据 ActiveState 的研究《",-1)),n(a,{href:"https://www.activestate.com/company/press/press-releases/activestate-developer-survey-examines-open-source-challenges/"},{default:r(()=>[...e[0]||(e[0]=[t("2018 年开发者调查：开源运行时的痛苦",-1)])]),_:1}),e[2]||(e[2]=t("》显示，超过一半的开发人员（具体为 51%），每天只需要花费 1-4 小时的时间进行编程。换句话说，大多数开发人员花费不到一半的时间编程。根据调查，一半的开发人员认为安全是他们最大的担忧之一，但是由于公司政策方面的原因，67% 的开发人员选择在编程时不添加新的语言。",-1))]),e[22]||(e[22]=d('<p>结果是开发人员不得不投入更多的精力在非编码的活动上，例如在构建软件和语言之后检查软件的安全性和合规性标准。而且由于公司政策的原因，他们无法选择适合的开发工具或语言。他们的满意度会下降，同时风险提高。</p><p>因此，开发人员无法将时间投入在高价值的工作上。这会带来额外的商业风险，因为他们的软件上市时间变慢了，并且公司因为没有授权开发人员在不受公司政策影响的前提下决定“最佳的”技术的能力，从而增加了技术债务。</p><h3 id="纳入安全性和合规性的工作流程" tabindex="-1">纳入安全性和合规性的工作流程 <a class="header-anchor" href="#纳入安全性和合规性的工作流程" aria-label="Permalink to “纳入安全性和合规性的工作流程”">​</a></h3><p>我们如何解决这个问题呢？一种方式是通过四个简单的步骤将安全性和合规性的工作流程集成到软件开发中：</p><h4 id="_1、集中你的力量" tabindex="-1">1、集中你的力量 <a class="header-anchor" href="#_1、集中你的力量" aria-label="Permalink to “1、集中你的力量”">​</a></h4><p>获得所有相关人员的支持，这是一个经常被遗忘但却至关重要的第一步。确保考虑到了广泛的利益相关者，包括：</p><ul><li>开发运维（DevOps）</li><li>开发人员</li><li>信息安全</li><li>合法/合规</li><li>IT 安全</li></ul><p>利益相关者想要了解相关的商业利益，因此要为消除软件构建后的安全和合规性检查点提供坚实的理由。你可以在构建你的商业案例中考虑以下任何一个（或者全部）因素：节省时间、机会成本和开发人员生产力。在开发流程中，你也可以通过集成安全性和合规性来避免语言的改造。</p><h4 id="_2、寻找可信赖的资源" tabindex="-1">2、寻找可信赖的资源 <a class="header-anchor" href="#_2、寻找可信赖的资源" aria-label="Permalink to “2、寻找可信赖的资源”">​</a></h4><p>接下来，选择可使用的可信资源，以及他们的许可证和安全要求。考虑到如下相关信息：</p><ul><li>基于环境或应用程序类型的使用限制以及每种语言的版本控制</li><li>允许哪些开源组件，例如，特定的程序包</li><li>哪种环境类型可以使用哪种许可证（例如，研究与生产）</li><li>安全级别的定义、可接受的脆弱性风险等级、什么样的风险级别会触发一个措施，这个措施是什么并且谁来负责它的执行</li></ul><h4 id="_3、从一开始就纳入安全性和合规性" tabindex="-1">3、从一开始就纳入安全性和合规性 <a class="header-anchor" href="#_3、从一开始就纳入安全性和合规性" aria-label="Permalink to “3、从一开始就纳入安全性和合规性”">​</a></h4><p>纳入安全性和合规性的工作流程的结果是，它最终将安全性和合规性融入到代码的第一行。它消除了公司政策的拖累，因为你是按照规范进行编码，而不是必须事后解决问题。但要做到这一点，请考虑在构建代码时采用自动扫描代码的机制，以及使用无代理监控你的运行时代码。你可以节省时间，还可以通过编程实施策略来确保整个组织的合规性。</p><h4 id="_4、监控、报告和更新" tabindex="-1">4、监控、报告和更新 <a class="header-anchor" href="#_4、监控、报告和更新" aria-label="Permalink to “4、监控、报告和更新”">​</a></h4><p>出现新的漏洞，新的补丁和版本也会出现。所以，将代码部署到生产中以及运行代码时，需要考虑安全性和合规性。你需要知道哪些（如果有的话）代码存在风险以及该代码在何处运行。所以，部署和运行代码的过程应该包括监视、报告和更新生产中的代码。</p><p>通过一开始就在你的软件开发过程中集成安全性和合规性，你还可以在部署后跟踪代码的运行位置，并在新的威胁出现时获得警报。你也能追踪当你的应用程序何时受到攻击，并通过自动执行软件策略做出响应。</p><p>如果你的软件开发过程中已经引入了安全性和合规性的工作流程，你将会提高你的生产率。你将能够通过增加编码时间、提高安全性和稳定性、以及在维护和发现安全性和合规性的威胁方面节省的成本和时间来衡量价值。</p><h3 id="集成所带来的幸福" tabindex="-1">集成所带来的幸福 <a class="header-anchor" href="#集成所带来的幸福" aria-label="Permalink to “集成所带来的幸福”">​</a></h3><p>如果你不开发和更新软件，你的组织将无法前进。开发人员是公司成功的关键，这意味着他们需要快速编写代码的工具和自由。尽管合规性和安全性至关重要，但你不能让这个需求阻碍你的发展。开发人员显然很担心安全性，因此最好的办法就是“左移”，从一开始就集成安全性和合规性的工作流程。你将可以做更多的事情，在第一次就可以完成，而花费更少的时间进行代码更新。</p><hr>',20)),l("p",null,[e[4]||(e[4]=t("via: ",-1)),n(a,{href:"https://opensource.com/article/19/2/developer-happiness"},{default:r(()=>[...e[3]||(e[3]=[t("https://opensource.com/article/19/2/developer-happiness",-1)])]),_:1})]),l("p",null,[e[9]||(e[9]=t("作者：",-1)),n(a,{href:"https://opensource.com/users/bartcopeland"},{default:r(()=>[...e[5]||(e[5]=[t("Bart Copeland",-1)])]),_:1}),e[10]||(e[10]=t(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[6]||(e[6]=[t("lujun9972",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),n(a,{href:"https://github.com/chenmu-kk"},{default:r(()=>[...e[7]||(e[7]=[t("chenmu-kk",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[15]||(e[15]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const g=o(u,[["render",m]]);export{C as __pageData,g as default};
